        if scale == 'atomic':
            rho_SCm = self.rho_vac_SCm_atomic
            rho_UA = CONSTANTS.get('rho_vac_UA_atomic', 1.60e20)
            level = 10
        else:
            rho_SCm = self.rho_vac_SCm_solar
            rho_UA = self.rho_vac_UA_solar
            level = 13
        
        # Calculate ratios
        ratio_UA_to_SCm = rho_UA / rho_SCm
        ratio_SCm_to_A = rho_SCm / self.rho_vac_A
        ratio_SCm_to_CMB = rho_SCm / self.rho_CMB
        ratio_SCm_to_dark = rho_SCm / self.rho_dark_energy
        combined_sum = rho_UA + rho_SCm
