    def validate_v_SCm_physics(self) -> dict:
        """
        Validate v_SCm physics calculations.
        
        Returns:
            Dict with validation results
        """
        tests_passed = 0
        tests_failed = 0
        results = []
        
        # Test 1: v_SCm value is 10^8 m/s
        expected_val = 1e8
        if abs(self.v_SCm / expected_val - 1.0) < 0.01:
            tests_passed += 1
            results.append(('v_SCm = 10⁸ m/s', 'PASS', f'{self.v_SCm:.0e}'))
        else:
            tests_failed += 1
            results.append(('v_SCm = 10⁸ m/s', 'FAIL', f'{self.v_SCm:.0e}'))
        
        # Test 2: v_SCm < c (subluminal)
        if self.v_SCm < self.c:
            tests_passed += 1
            results.append(('v_SCm < c (subluminal)', 'PASS', 
                          f'{self.v_SCm:.0e} < {self.c:.2e}'))
        else:
            tests_failed += 1
            results.append(('v_SCm < c (subluminal)', 'FAIL',
                          f'{self.v_SCm:.0e} vs {self.c:.2e}'))
        
        # Test 3: v_SCm/c ≈ 1/3
        ratio = self.v_SCm / self.c
        if 0.30 < ratio < 0.37:
            tests_passed += 1
            results.append(('v_SCm/c ≈ 1/3', 'PASS', f'{ratio:.4f}'))
        else:
            tests_failed += 1
            results.append(('v_SCm/c ≈ 1/3', 'FAIL', f'{ratio:.4f}'))
        
        # Test 4: v_SCm² = 10^16 m²/s²
        expected_squared = 1e16
        actual_squared = self.v_SCm**2
        if abs(actual_squared / expected_squared - 1.0) < 0.01:
            tests_passed += 1
            results.append(('v_SCm² = 10¹⁶ m²/s²', 'PASS', f'{actual_squared:.0e}'))
        else:
            tests_failed += 1
            results.append(('v_SCm² = 10¹⁶ m²/s²', 'FAIL', f'{actual_squared:.0e}'))
        
        # Test 5: E_react(t=0) calculation is reasonable
        E_react, _ = self.compute_E_react_from_v_SCm(t=0)
        if 500 < E_react < 1000:  # Expected ~709
            tests_passed += 1
            results.append(('E_react(t=0) ≈ 709', 'PASS', f'{E_react:.1f}'))
        else:
            tests_failed += 1
            results.append(('E_react(t=0) ≈ 709', 'FAIL', f'{E_react:.1f}'))
        
        # Test 6: 1 AU travel time ~25 minutes
        AU = 1.496e11
        time_SCm_minutes = (AU / self.v_SCm) / 60
        if 20 < time_SCm_minutes < 30:  # Expected ~25 minutes
            tests_passed += 1
            results.append(('1 AU travel ≈ 25 min', 'PASS', f'{time_SCm_minutes:.1f} min'))
        else:
            tests_failed += 1
            results.append(('1 AU travel ≈ 25 min', 'FAIL', f'{time_SCm_minutes:.1f} min'))
        
        return {
            'tests_passed': tests_passed,
            'tests_failed': tests_failed,
            'total_tests': tests_passed + tests_failed,
            'pass_rate': tests_passed / (tests_passed + tests_failed) * 100,
            'results': results
        }
    
    def get_model_description(self) -> str:
        """Return detailed model description."""
        return self.__doc__


