    def compute_lepton_energy_density(self, lepton: str, t: float = 0,
                                       t_n: float = 0, n: int = 2) -> Tuple[float, str]:
        """
        Compute lepton energy density in UQFF.
        
        U_e = λ_e × ρ_vac,[SCm] × ρ_vac,[UA] × ω_e(t) × cos(πt_n)
              × (1 + f_TRZ) × e^(-[SSq]^n × 26 × e^(-π-t))
        
        Args:
            lepton: Lepton type ('e', 'mu', 'tau')
            t: Time (s)
            t_n: Negative time factor
            n: Quantum state (default 2 for electron)
            
        Returns:
            Tuple of (U_e in J/m³, explanation string)
        """
        if lepton not in self.lepton_omegas:
            lepton = 'e'
        
        lambda_l = CONSTANTS.get(f'lambda_{lepton}', 1.0)
        omega_l = self.lepton_omegas.get(lepton, 1e19)
        
        cos_term = np.cos(np.pi * t_n)
        TRZ_factor = 1 + self.f_TRZ
        nonlocal_term, _ = self.compute_nonlocal_jump_probability(t, n)
        nonlocal_exp = np.exp(-nonlocal_term)
        
        U_l = (lambda_l * self.rho_vac_SCm * self.rho_vac_UA * omega_l
               * cos_term * TRZ_factor * nonlocal_exp)
        
        explanation = f"""
    LEPTON ENERGY DENSITY ({lepton.upper()})
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        U_l = λ_l × ρ_vac,[SCm] × ρ_vac,[UA] × ω_l × cos(πt_n)
              × (1 + f_TRZ) × e^(-[SSq]^n × 26 × e^(-π-t))
    
    INPUTS:
        Lepton: {lepton}
        λ_{lepton} = {lambda_l}
        ω_{lepton} = {omega_l:.0e} rad/s
        t_n = {t_n}, t = {t}, n = {n}
    
    CALCULATION:
        cos(πt_n) = {cos_term:.4f}
        (1 + f_TRZ) = {TRZ_factor:.2f}
        Non-local exp = {nonlocal_exp:.6f}
        
        U_{lepton} = {U_l:.4e} J/m³
    
    PHYSICAL INTERPRETATION:
        Leptons are TOROIDAL VORTICES in [UA]. Electrons have a dual
        nature ([SCm] and [SCm']), enabling their unique electromagnetic
        properties and stability.
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return U_l, explanation
    
    def compute_neutrino_oscillation_probability(self, L: float, E_nu: float,
                                                   flavor_from: str = 'e',
                                                   flavor_to: str = 'mu') -> Tuple[float, str]:
        """
        Compute neutrino oscillation probability.
        
        P(ν_e → ν_μ) = sin²(2θ) × sin²(Δm² L / 4E_ν)
        
        Args:
            L: Distance traveled (m)
            E_nu: Neutrino energy (J)
            flavor_from: Initial flavor
            flavor_to: Final flavor
            
        Returns:
            Tuple of (probability, explanation string)
        """
        # Select appropriate mixing angle and mass-squared difference
        theta = CONSTANTS.get('theta_12', 0.587)  # Solar mixing
        delta_m_sq = CONSTANTS.get('delta_m21_sq', 7.53e-5)  # eV²
        
        # Convert delta_m_sq to SI units (kg² c⁴ / ℏ² c²)
        # For simplicity, use the oscillation formula in natural units
        # and scale appropriately
        
        sin_2theta_sq = np.sin(2 * theta)**2
        osc_arg = delta_m_sq * L / (4 * E_nu / self.q)  # E in eV
        sin_osc_sq = np.sin(osc_arg)**2
        
        P_osc = sin_2theta_sq * sin_osc_sq
        
        explanation = f"""
    NEUTRINO OSCILLATION PROBABILITY
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        P(ν_{flavor_from} → ν_{flavor_to}) = sin²(2θ) × sin²(Δm² L / 4E_ν)
    
    INPUTS:
        L = {L:.4e} m (baseline distance)
        E_ν = {E_nu:.4e} J
        θ = {theta:.4f} rad (mixing angle)
        Δm² = {delta_m_sq:.4e} eV²
    
    CALCULATION:
        sin²(2θ) = sin²({2*theta:.4f}) = {sin_2theta_sq:.4f}
        Oscillation argument = {osc_arg:.4f}
        sin²(arg) = {sin_osc_sq:.4f}
        
        P = {P_osc:.4f}
    
    PHYSICAL INTERPRETATION:
        Neutrinos OSCILLATE between flavors (e, μ, τ) as they propagate
        through [UA]. This is modeled as transitions between the 26
        quantum states, with the mixing angles determining the
        transition amplitudes.
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return P_osc, explanation
    
    # ═══════════════════════════════════════════════════════════════════════════
    # BOSON METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def compute_higgs_energy_density(self, t: float = 0, n: int = 1) -> Tuple[float, str]:
        """
        Compute Higgs boson energy density fluctuation in [UA].
        
        U_H = λ_H × ρ_vac,[UA] × ω_H(t) × e^(-[SSq]^n × 26 × e^(-π-t))
              × (1 + f_quasi)
        
        Args:
            t: Time (s)
            n: Quantum state (1-26)
            
        Returns:
            Tuple of (U_H in J/m³, explanation string)
        """
        lambda_H = CONSTANTS.get('lambda_H', 1.0)
        omega_H = self.boson_omegas.get('H', 1e22)
        
        nonlocal_term, _ = self.compute_nonlocal_jump_probability(t, n)
        nonlocal_exp = np.exp(-nonlocal_term)
        quasi_factor = 1 + self.f_quasi
        
        U_H = lambda_H * self.rho_vac_UA * omega_H * nonlocal_exp * quasi_factor
        
        explanation = f"""
    HIGGS BOSON ENERGY DENSITY
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        U_H = λ_H × ρ_vac,[UA] × ω_H × e^(-[SSq]^n × 26 × e^(-π-t))
              × (1 + f_quasi)
    
    INPUTS:
        λ_H = {lambda_H}
        ω_H = {omega_H:.0e} rad/s
        ρ_vac,[UA] = {self.rho_vac_UA:.4e} J/m³
        t = {t}, n = {n}
    
    CALCULATION:
        Non-local exp = {nonlocal_exp:.6f}
        (1 + f_quasi) = {quasi_factor:.3f}
        
        U_H = {U_H:.4e} J/m³
    
    PHYSICAL INTERPRETATION:
        The Higgs boson is modeled as a FLUCTUATION in [UA] that imparts
        mass to particles through its vacuum expectation value:
        
        v_H = 246 GeV
        m_f = y_f × v_H (Yukawa coupling)
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return U_H, explanation
    
    def compute_higgs_potential(self, phi_H: float) -> Tuple[float, str]:
        """
        Compute Higgs field potential.
        
        V_H = (1/2)μ² φ_H² + (1/4)λ φ_H⁴
        
        Args:
            phi_H: Higgs field value (GeV)
            
        Returns:
            Tuple of (V_H in GeV⁴, explanation string)
        """
        mu_sq = CONSTANTS.get('mu_H_squared', -8.9e4)  # GeV²
        lambda_quartic = CONSTANTS.get('lambda_H_quartic', 0.13)
        
        V_H = 0.5 * mu_sq * phi_H**2 + 0.25 * lambda_quartic * phi_H**4
        
        explanation = f"""
    HIGGS FIELD POTENTIAL
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        V_H = (1/2)μ² φ_H² + (1/4)λ φ_H⁴
    
    INPUTS:
        μ² = {mu_sq:.2e} GeV² (negative for spontaneous symmetry breaking)
        λ = {lambda_quartic} (quartic self-coupling)
        φ_H = {phi_H:.2e} GeV
    
    CALCULATION:
        V_H = 0.5 × {mu_sq:.2e} × ({phi_H:.2e})² + 0.25 × {lambda_quartic} × ({phi_H:.2e})⁴
            = {V_H:.4e} GeV⁴
    
    PHYSICAL INTERPRETATION:
        The Higgs potential has a "Mexican hat" shape due to μ² < 0,
        leading to SPONTANEOUS SYMMETRY BREAKING. The vacuum expectation
        value v_H ≈ 246 GeV is the minimum of this potential.
        
        In UQFF, this is linked to [UA] fluctuations that generate mass
        for particles via Yukawa couplings.
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return V_H, explanation
    
    def compute_mass_from_yukawa(self, particle: str) -> Tuple[float, str]:
        """
        Compute particle mass from Yukawa coupling to Higgs.
        
        m_f = y_f × v_H
        
        Args:
            particle: Particle name (e.g., 'e', 't', 'b')
            
        Returns:
            Tuple of (mass in GeV/c², explanation string)
        """
        v_H = CONSTANTS.get('v_H', 246e9) / 1e9  # Convert to GeV
        
        yukawa_map = {
            'e': CONSTANTS.get('y_e', 2.1e-6),
            'mu': CONSTANTS.get('y_mu', 4.3e-4),
            'tau': CONSTANTS.get('y_tau', 7.2e-3),
            'u': CONSTANTS.get('y_u', 8.9e-6),
            'd': CONSTANTS.get('y_d', 1.9e-5),
            's': CONSTANTS.get('y_s', 3.9e-4),
            'c': CONSTANTS.get('y_c', 5.2e-3),
            'b': CONSTANTS.get('y_b', 1.7e-2),
            't': CONSTANTS.get('y_t', 0.70)
        }
        
        y_f = yukawa_map.get(particle, 1e-6)
        m_f = y_f * v_H  # GeV/c²
        
        explanation = f"""
    MASS FROM YUKAWA COUPLING ({particle.upper()})
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        m_f = y_f × v_H
    
    INPUTS:
        y_{particle} = {y_f:.4e} (Yukawa coupling)
        v_H = {v_H:.0f} GeV (Higgs VEV)
    
    CALCULATION:
        m_{particle} = {y_f:.4e} × {v_H:.0f} GeV
                     = {m_f:.4e} GeV/c²
    
    PHYSICAL INTERPRETATION:
        Particles acquire mass through their coupling to the Higgs field.
        Stronger Yukawa couplings → larger masses:
        • Top quark (y_t ≈ 0.70) → m_t ≈ 173 GeV (heaviest)
        • Electron (y_e ≈ 2×10⁻⁶) → m_e ≈ 0.5 MeV (light)
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return m_f, explanation
    
    # ═══════════════════════════════════════════════════════════════════════════
    # HADRON METHODS (PROTON, NEUTRON, KAONS)
    # ═══════════════════════════════════════════════════════════════════════════
    
    def compute_proton_energy_density(self, t: float = 0, t_n: float = 0, 
                                       n: int = 1) -> Tuple[float, str]:
        """
        Compute proton energy density as sum of quark and gluon contributions.
        
        U_p = Σ(U_q for uud) + U_g
        
        Args:
            t: Time (s)
            t_n: Negative time factor
            n: Quantum state (1-26)
            
        Returns:
            Tuple of (U_p in J/m³, explanation string)
        """
        U_u, _ = self.compute_quark_energy_density('u', t, t_n, n)
        U_d, _ = self.compute_quark_energy_density('d', t, t_n, n)
        U_g, _ = self.compute_gluon_energy_density(t, n)
        
        U_p = 2 * U_u + U_d + U_g
        
        explanation = f"""
    PROTON ENERGY DENSITY (uud)
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        U_p = 2×U_u + U_d + U_g
    
    QUARK COMPOSITION:
        Proton = u + u + d (up + up + down)
    
    COMPONENT CONTRIBUTIONS:
        U_u = {U_u:.4e} J/m³ (per up quark)
        U_d = {U_d:.4e} J/m³ (down quark)
        U_g = {U_g:.4e} J/m³ (gluon binding)
    
    CALCULATION:
        U_p = 2 × {U_u:.4e} + {U_d:.4e} + {U_g:.4e}
            = {U_p:.4e} J/m³
    
    NOTE:
        The gluon contribution DOMINATES the energy density, reflecting
        that ~99% of hadron mass comes from gluon binding energy, not
        quark rest masses.
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return U_p, explanation
    
    def compute_neutron_energy_density(self, t: float = 0, t_n: float = 0,
                                        n: int = 1) -> Tuple[float, str]:
        """
        Compute neutron energy density as sum of quark and gluon contributions.
        
        U_n = Σ(U_q for udd) + U_g
        
        Args:
            t: Time (s)
            t_n: Negative time factor
            n: Quantum state (1-26)
            
        Returns:
            Tuple of (U_n in J/m³, explanation string)
        """
        U_u, _ = self.compute_quark_energy_density('u', t, t_n, n)
        U_d, _ = self.compute_quark_energy_density('d', t, t_n, n)
        U_g, _ = self.compute_gluon_energy_density(t, n)
        
        U_n = U_u + 2 * U_d + U_g
        
        explanation = f"""
    NEUTRON ENERGY DENSITY (udd)
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        U_n = U_u + 2×U_d + U_g
    
    QUARK COMPOSITION:
        Neutron = u + d + d (up + down + down)
    
    COMPONENT CONTRIBUTIONS:
        U_u = {U_u:.4e} J/m³ (up quark)
        U_d = {U_d:.4e} J/m³ (per down quark)
        U_g = {U_g:.4e} J/m³ (gluon binding)
    
    CALCULATION:
        U_n = {U_u:.4e} + 2 × {U_d:.4e} + {U_g:.4e}
            = {U_n:.4e} J/m³
    
    COMPARISON TO PROTON:
        U_n ≈ U_p (gluon binding dominates both)
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return U_n, explanation
    
    def compute_kaon_energy_density(self, kaon_type: str = 'K_plus', t: float = 0,
                                     t_n: float = 0, n: int = 3) -> Tuple[float, str]:
        """
        Compute kaon energy density.
        
        U_K = λ_K × ρ_vac,[SCm] × ρ_vac,[UA] × ω_K × cos(πt_n) × (1 + f_TRZ)
        
        Args:
            kaon_type: 'K_plus' (us̄) or 'K_zero' (ds̄)
            t: Time (s)
            t_n: Negative time factor
            n: Quantum state (default 3)
            
        Returns:
            Tuple of (U_K in J/m³, explanation string)
        """
        lambda_K = 1.0
        omega_K = 1e20
        
        cos_term = np.cos(np.pi * t_n)
        TRZ_factor = 1 + self.f_TRZ
        
        U_K = lambda_K * self.rho_vac_SCm * self.rho_vac_UA * omega_K * cos_term * TRZ_factor
        
        # Mass energy
        mass = self.hadron_masses.get(kaon_type, self.hadron_masses['K_plus'])
        E_K, _ = self.compute_mass_energy_modified(mass, n)
        
        # Decay rate
        tau_K = self.decay_lifetimes.get(kaon_type, 1.24e-8)
        
        quark_content = 'us̄' if kaon_type == 'K_plus' else 'ds̄'
        
        explanation = f"""
    KAON ENERGY DENSITY ({kaon_type})
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        U_K = λ_K × ρ_vac,[SCm] × ρ_vac,[UA] × ω_K × cos(πt_n) × (1 + f_TRZ)
    
    QUARK CONTENT:
        {kaon_type} = {quark_content} (quark-antiquark pair)
    
    CALCULATION:
        U_K = {U_K:.4e} J/m³
    
    MASS ENERGY (n={n}):
        E_K = m_K × c² × e^(n/26) = {E_K:.4e} J
    
    DECAY:
        τ_K = {tau_K:.4e} s
        Γ_K = 1/τ_K = {1/tau_K:.4e} s⁻¹
        
    Kaons decay via the WEAK FORCE, with decay rates modeled as:
        Γ_K = (1/τ_K) × e^(-t/τ_K)
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return U_K, explanation
    
    def compute_decay_rate(self, particle: str, t: float = 0) -> Tuple[float, str]:
        """
        Compute particle decay rate.
        
        Γ = (1/τ) × e^(-t/τ)
        
        Args:
            particle: Particle name (e.g., 'neutron', 'K_plus', 'muon')
            t: Time since creation (s)
            
        Returns:
            Tuple of (decay rate Γ in s⁻¹, explanation string)
        """
        tau = self.decay_lifetimes.get(particle, 1.0)
        Gamma = (1/tau) * np.exp(-t/tau)
        survival_prob = np.exp(-t/tau)
        
        explanation = f"""
    PARTICLE DECAY RATE ({particle})
    ═══════════════════════════════════════════════════════════════════════════════
    
    FORMULA:
        Γ(t) = (1/τ) × e^(-t/τ)
        P_survival = e^(-t/τ)
    
    INPUTS:
        τ_{particle} = {tau:.4e} s (mean lifetime)
        t = {t:.4e} s (time since creation)
    
    CALCULATION:
        Γ = (1/{tau:.4e}) × e^(-{t:.4e}/{tau:.4e})
          = {1/tau:.4e} × {np.exp(-t/tau):.6f}
          = {Gamma:.4e} s⁻¹
        
        P_survival = {survival_prob:.4f} ({survival_prob*100:.2f}%)
    
    PHYSICAL INTERPRETATION:
        Particles decay via the WEAK FORCE in UQFF. The decay rate in the
        Aether context may differ from vacuum due to [UA] interactions.
    ═══════════════════════════════════════════════════════════════════════════════
    """
        return Gamma, explanation
    
    # ═══════════════════════════════════════════════════════════════════════════
    # VALIDATION METHODS
    # ═══════════════════════════════════════════════════════════════════════════
    
    def validate_standard_model_physics(self) -> dict:
        """
        Validate Standard Model UQFF integration physics.
        
        Returns:
            Dict with validation results
        """
        tests_passed = 0
        tests_failed = 0
        results = []
        
        # Test 1: Up quark energy density calculation
        # Note: Very small due to ρ_vac,[SCm] × ρ_vac,[UA] ≈ 10^-72
        U_u, _ = self.compute_quark_energy_density('u', t=0, t_n=0, n=1)
        if 1e-55 < U_u < 1e-48:  # Expected ~10^-52 J/m³
            tests_passed += 1
            results.append(('Up quark energy density', 'PASS', f'{U_u:.2e} J/m³'))
        else:
            tests_failed += 1
            results.append(('Up quark energy density', 'FAIL', f'{U_u:.2e} J/m³'))
        
        # Test 2: Electron energy density
        U_e, _ = self.compute_lepton_energy_density('e', t=0, t_n=0, n=2)
        if 1e-56 < U_e < 1e-49:  # Expected ~10^-53 J/m³
            tests_passed += 1
            results.append(('Electron energy density', 'PASS', f'{U_e:.2e} J/m³'))
        else:
            tests_failed += 1
            results.append(('Electron energy density', 'FAIL', f'{U_e:.2e} J/m³'))
        
        # Test 3: Gluon energy density dominates
        U_g, _ = self.compute_gluon_energy_density(t=0, n=1)
        if U_g > U_u * 100:  # Gluons should dominate
            tests_passed += 1
            results.append(('Gluon >> quark energy', 'PASS', f'{U_g/U_u:.0f}×'))
        else:
            tests_failed += 1
            results.append(('Gluon >> quark energy', 'FAIL', f'{U_g/U_u:.2f}×'))
        
        # Test 4: Proton energy density (gluon-dominated)
        U_p, _ = self.compute_proton_energy_density(t=0, t_n=0, n=1)
        if abs(U_p / U_g - 1.0) < 0.01:  # Proton ≈ gluon binding
            tests_passed += 1
            results.append(('Proton ≈ gluon binding', 'PASS', f'{U_p/U_g:.4f}'))
        else:
            tests_failed += 1
            results.append(('Proton ≈ gluon binding', 'FAIL', f'{U_p/U_g:.4f}'))
        
        # Test 5: Quantum state mass enhancement
        E_u_n1, _ = self.compute_quark_mass_energy('u', n=1)
        E_u_n26, _ = self.compute_quark_mass_energy('u', n=26)
        enhancement = E_u_n26 / E_u_n1
        if 2.5 < enhancement < 2.8:  # Should be e¹/e^(1/26) ≈ 2.62
            tests_passed += 1
            results.append(('n=26 enhancement ≈ e', 'PASS', f'{enhancement:.3f}'))
        else:
            tests_failed += 1
            results.append(('n=26 enhancement ≈ e', 'FAIL', f'{enhancement:.3f}'))
        
        # Test 6: Top quark is heaviest fermion
        m_t = CONSTANTS.get('m_t', 3.08e-25)
        m_b = CONSTANTS.get('m_b', 7.49e-27)
        if m_t > m_b * 10:
            tests_passed += 1
            results.append(('Top > 10× bottom', 'PASS', f'{m_t/m_b:.1f}×'))
        else:
            tests_failed += 1
            results.append(('Top > 10× bottom', 'FAIL', f'{m_t/m_b:.1f}×'))
        
        # Test 7: Higgs VEV ≈ 246 GeV
        v_H = CONSTANTS.get('v_H', 246e9) / 1e9  # GeV
        if 240 < v_H < 250:
            tests_passed += 1
            results.append(('Higgs VEV ≈ 246 GeV', 'PASS', f'{v_H:.0f} GeV'))
        else:
            tests_failed += 1
            results.append(('Higgs VEV ≈ 246 GeV', 'FAIL', f'{v_H:.0f} GeV'))
        
        # Test 8: Neutron lifetime ≈ 879 s
        tau_n = CONSTANTS.get('tau_n', 879.4)
        if 870 < tau_n < 890:
            tests_passed += 1
            results.append(('Neutron τ ≈ 879 s', 'PASS', f'{tau_n:.1f} s'))
        else:
            tests_failed += 1
            results.append(('Neutron τ ≈ 879 s', 'FAIL', f'{tau_n:.1f} s'))
        
        return {
            'tests_passed': tests_passed,
            'tests_failed': tests_failed,
            'total_tests': tests_passed + tests_failed,
            'pass_rate': tests_passed / (tests_passed + tests_failed) * 100,
            'results': results
        }
    
    def get_model_description(self) -> str:
        """Return detailed model description."""
        return self.__doc__


