        all_results.append({'name': 'Final Parsec', 'passed': fp_pass})
        
        # CGM Metal Retention
        cgm_pass, cgm_tests, _ = self.cgm_model.validate_CGM_model()
        all_results.append({'name': 'CGM Metal Retention', 'passed': cgm_pass})
        
