class USPRModel:
    """
    Universal Shifting Polarity Reaction (USPR) Model
    
    From the document: The USPR reaction between {[UA]; (UA')+[SCm],
    (UA'')+[SCm'], (UA''')+[SCm''']} is responsible for all elemental creation
    in the universe.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    USPR: [UA] + (UA')+[SCm] + (UA'')+[SCm'] + (UA''')+[SCm'''] → Elements
    
    Where:
        [UA]    : Universal Aether (base)
        (UA')   : First excited state of Aether
        (UA'')  : Second excited state
        (UA''') : Third excited state
        [SCm]   : Superconductive Material (base)
        [SCm']  : First modified SCm
        [SCm'']: Second modified SCm
        [SCm''']: Third modified SCm
    
    REACTION PROPERTIES:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Every star and atom have unique amounts of (UA')+[SCm] bound
    - Produces ranges and magnitudes of similar species
    - Creates "widely banded" species as complexity grows
    - Induces crystalline-like quantum wave pattern diversity over time
    
    The USPR is the fundamental reaction driving:
    1. Pseudo-monopole creation at stellar cores
    2. Elemental nucleosynthesis
    3. Universal Magnetism [Um_i] generation
    """
    
    def __init__(self):
        """Initialize USPR Model."""
        # Reactant states
        self.UA_states = {
            'UA': {'level': 0, 'energy': 1e-20, 'description': 'Base Aether'},
            "UA'": {'level': 1, 'energy': 1e-19, 'description': 'First excited'},
            "UA''": {'level': 2, 'energy': 1e-18, 'description': 'Second excited'},
            "UA'''": {'level': 3, 'energy': 1e-17, 'description': 'Third excited'}
        }
        
        self.SCm_states = {
            'SCm': {'level': 0, 'energy': 1e-21, 'description': 'Base SCm'},
            "SCm'": {'level': 1, 'energy': 1e-20, 'description': 'First modified'},
            "SCm''": {'level': 2, 'energy': 1e-19, 'description': 'Second modified'},
            "SCm'''": {'level': 3, 'energy': 1e-18, 'description': 'Third modified'}
        }
        
        # Binding energies
        self.binding_energy_per_pair = 1e-22  # J per (UA)+[SCm] pair
    
    def compute_USPR_energy(self, n_pairs: int = 1,
                             excitation_level: int = 0) -> Tuple[float, str]:
        """
        Compute USPR reaction energy.
        
        E_USPR = n × E_binding × (1 + level/3)
        
        Args:
            n_pairs: Number of (UA)+[SCm] pairs
            excitation_level: Excitation state (0-3)
        
        Returns:
            E_USPR: USPR energy (J)
            steps: Derivation string
        """
        level_factor = 1 + excitation_level / 3
        E_USPR = n_pairs * self.binding_energy_per_pair * level_factor
        
        steps = f"""
    USPR REACTION ENERGY
    ══════════════════════════════════════════════════════════════════
    
    Universal Shifting Polarity Reaction
    
    REACTANTS:
        [UA] + (UA')+[SCm] + (UA'')+[SCm'] + (UA''')+[SCm''']
    
    E_USPR = n × E_binding × (1 + level/3)
    
    PARAMETERS:
        n_pairs = {n_pairs}
        E_binding = {self.binding_energy_per_pair:.4e} J
        Excitation level = {excitation_level}
        Level factor = 1 + {excitation_level}/3 = {level_factor:.4f}
    
    CALCULATION:
        E_USPR = {n_pairs} × {self.binding_energy_per_pair:.4e} × {level_factor:.4f}
               = {E_USPR:.4e} J
    
    OUTPUT: Creates pseudo-monopole and elemental nuclei
    ══════════════════════════════════════════════════════════════════"""
        
        return E_USPR, steps
    
    def compute_elemental_creation_rate(self, M_star: float = None,
                                          age_Gyr: float = 4.6) -> Tuple[float, str]:
        """
        Compute elemental creation rate from USPR.
        
        Rate = (M_star/M_sun) × (age/age_sun) × base_rate
        
        Args:
            M_star: Stellar mass (kg)
            age_Gyr: Stellar age in Gyr
        
        Returns:
            rate: Elemental creation rate (elements/s estimate)
            steps: Derivation string
        """
        M_sun = CONSTANTS.get('M_Sun', 1.989e30)
        M_star = M_star if M_star is not None else M_sun
        age_sun = 4.6  # Gyr
        
        base_rate = 1e30  # elements/s (order of magnitude estimate)
        rate = (M_star / M_sun) * (age_Gyr / age_sun) * base_rate
        
        steps = f"""
    USPR ELEMENTAL CREATION RATE
    ══════════════════════════════════════════════════════════════════
    
    From document: USPR is responsible for ALL elemental creation
    
    Rate = (M_star/M_sun) × (age/age_sun) × base_rate
    
    PARAMETERS:
        M_star = {M_star:.4e} kg
        M_sun = {M_sun:.4e} kg
        age = {age_Gyr} Gyr
        age_sun = {age_sun} Gyr
        base_rate = {base_rate:.4e} elements/s
    
    CALCULATION:
        Rate = ({M_star/M_sun:.4f}) × ({age_Gyr/age_sun:.4f}) × {base_rate:.4e}
             = {rate:.4e} elements/s
    
    NOTE: Creates "widely banded" species through crystalline-like
    quantum wave pattern diversity over time
    ══════════════════════════════════════════════════════════════════"""
        
        return rate, steps
    
    def compute_species_diversity(self, Z_max: int = 118) -> Tuple[int, str]:
        """
        Compute species diversity from USPR (elements and isotopes).
        
        Args:
            Z_max: Maximum atomic number
        
        Returns:
            n_species: Number of distinct species
            steps: Derivation string
        """
        # Approximate: each element has ~2-3 stable isotopes on average
        avg_isotopes = 2.5
