# UNIFIED MODEL: SOLAR DOMAIN (Hill Sphere + Oort Cloud Unification)
# ═══════════════════════════════════════════════════════════════════════════════

class SolarDomainModel:
    """
    Solar Domain Model - Unified Hill Sphere + Oort Cloud Boundaries
    
    INTEGRATION: Combines HillSphereModel (230k AU theoretical) with 
    OortCloudBoundaryModel (100k AU practical) into nested boundaries.
    
    NESTED BOUNDARY STRUCTURE:
    ─────────────────────────────────────────────────────────────────────────────
    
    Zone 1: PLANETARY ZONE (0 - 50 AU)
        - Classical Keplerian orbits
        - Dominated by solar gravity
        - Contains all major planets + Kuiper Belt
    
    Zone 2: SCATTERED ZONE (50 - 2,000 AU)
        - Extreme TNOs (Sedna, The Goblin)
        - Chaotic orbits, possible planet interactions
        
    Zone 3: INNER OORT CLOUD (2,000 - 20,000 AU)
        - Spherical cloud of comets
        - Weak but stable solar binding
        
    Zone 4: OUTER OORT CLOUD (20,000 - 100,000 AU)
        - Practical limit of solar control
        - Long-period comet reservoir
        
    Zone 5: EXTENDED HILL SPHERE (100,000 - 230,000 AU)
        - Theoretical gravitational dominance
        - Subject to galactic perturbations
        - Marginally bound / transient objects
    
    BOUNDARY PHYSICS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Theoretical: r_H = a × (M_sun / 3M_gal)^(1/3) ≈ 230,000 AU
    Practical:   r_Oort ≈ 100,000 AU (galactic tides strip outer objects)
    """
    
    def __init__(self):
        """Initialize Solar Domain Model."""
        # Reference base models
        self.hill_model = HILL_SPHERE_MODEL
        self.oort_model = OORT_CLOUD_MODEL
        
        # Physical constants
        self.AU = 1.496e11
        self.ly = 9.461e15
        
        # Zone boundaries (AU)
        self.zones = {
            'planetary': {'inner': 0, 'outer': 50, 'color': 'blue'},
            'scattered': {'inner': 50, 'outer': 2000, 'color': 'cyan'},
            'inner_oort': {'inner': 2000, 'outer': 20000, 'color': 'green'},
            'outer_oort': {'inner': 20000, 'outer': 100000, 'color': 'yellow'},
            'extended_hill': {'inner': 100000, 'outer': 230000, 'color': 'red'}
        }
        
        # Key objects
        self.landmark_objects = {
            'Neptune': 30,
            'Pluto_aphelion': 49,
            'Eris_aphelion': 96,
            'Sedna_aphelion': 937,
            'The_Goblin_aphelion': 2300,
            'Inner_Oort_Edge': 2000,
            'Outer_Oort_Edge': 100000,
            'Hill_Sphere': 230000
        }
        
    def classify_distance(self, d_AU: float) -> Tuple[str, dict, str]:
        """
        Classify a distance into the appropriate solar domain zone.
        
        Args:
            d_AU: Distance from Sun (AU)
        
        Returns:
            zone_name: Name of the zone
            zone_info: Zone properties
            steps: Description
        """
        for zone_name, bounds in self.zones.items():
            if bounds['inner'] <= d_AU < bounds['outer']:
                zone_info = bounds.copy()
                zone_info['name'] = zone_name
                break
        else:
            zone_info = {'name': 'interstellar', 'inner': 230000, 'outer': float('inf')}
            zone_name = 'interstellar'
        
        d_ly = d_AU * self.AU / self.ly
        
        steps = f"""
    SOLAR DOMAIN CLASSIFICATION
    ══════════════════════════════════════════════════════════════════
    
    Distance: {d_AU:,.0f} AU = {d_ly:.4f} ly
    
    ZONE: {zone_name.upper().replace('_', ' ')}
    
    ZONE STRUCTURE (unified Hill + Oort):
    ──────────────────────────────────────────────────────────────────
    {'→ ' if zone_name == 'planetary' else '  '}Planetary:      0 - 50 AU
    {'→ ' if zone_name == 'scattered' else '  '}Scattered:      50 - 2,000 AU
    {'→ ' if zone_name == 'inner_oort' else '  '}Inner Oort:     2,000 - 20,000 AU
    {'→ ' if zone_name == 'outer_oort' else '  '}Outer Oort:     20,000 - 100,000 AU (practical limit)
    {'→ ' if zone_name == 'extended_hill' else '  '}Extended Hill:  100,000 - 230,000 AU (theoretical)
    ──────────────────────────────────────────────────────────────────
    
    BINDING STATUS: {'Strong solar binding' if zone_name in ['planetary', 'scattered'] else 'Weak solar binding' if zone_name in ['inner_oort', 'outer_oort'] else 'Marginal binding / transient' if zone_name == 'extended_hill' else 'Unbound / Interstellar'}
    ══════════════════════════════════════════════════════════════════"""
        
        return zone_name, zone_info, steps
    
    def compute_binding_energy(self, d_AU: float, 
                                 M_object: float = 1e12) -> Tuple[float, str]:
        """
        Compute gravitational binding energy at distance.
        
        E_bind = -G × M_sun × M_object / r
        
        Args:
            d_AU: Distance from Sun (AU)
            M_object: Object mass (kg, default ~comet)
        
        Returns:
            E_bind: Binding energy (J, negative = bound)
            steps: Derivation string
        """
        G = CONSTANTS.get('G', 6.674e-11)
        M_sun = CONSTANTS.get('M_Sun', 1.989e30)
        
        r = d_AU * self.AU
        E_bind = -G * M_sun * M_object / r
        
        # Escape velocity
        v_esc = np.sqrt(2 * G * M_sun / r)
        
        steps = f"""
    SOLAR BINDING ENERGY
    ══════════════════════════════════════════════════════════════════
    
    E_bind = -G × M_sun × M_object / r
    
    PARAMETERS:
        d = {d_AU:,.0f} AU = {r:.4e} m
        M_sun = {M_sun:.4e} kg
        M_object = {M_object:.4e} kg
    
    CALCULATION:
        E_bind = -{G:.4e} × {M_sun:.4e} × {M_object:.4e} / {r:.4e}
               = {E_bind:.4e} J
        
        v_escape = √(2GM/r) = {v_esc:.2e} m/s = {v_esc/1000:.4f} km/s
    
    ZONE COMPARISON:
        Neptune (30 AU): v_esc ≈ 7.7 km/s
        Outer Oort (100,000 AU): v_esc ≈ 0.13 km/s
        Hill Sphere (230,000 AU): v_esc ≈ 0.09 km/s
    ══════════════════════════════════════════════════════════════════"""
        
        return E_bind, steps
    
    def compute_zone_volumes(self) -> Tuple[dict, str]:
        """
        Compute volumes of each solar domain zone.
        
        Returns:
            volumes: Dictionary of zone volumes (AU³)
            steps: Description
        """
        volumes = {}
        
        for name, bounds in self.zones.items():
            r_inner = bounds['inner'] * self.AU
            r_outer = bounds['outer'] * self.AU
            V = (4/3) * np.pi * (r_outer**3 - r_inner**3)
            V_AU3 = V / (self.AU**3)
            volumes[name] = V_AU3
        
        total_V = sum(volumes.values())
        
        steps = """
    SOLAR DOMAIN ZONE VOLUMES
    ══════════════════════════════════════════════════════════════════
    
    V = (4/3)π × (r_outer³ - r_inner³)
    
    ZONE VOLUMES:
"""
        for name, V in volumes.items():
            pct = V / total_V * 100
            steps += f"        {name.replace('_', ' ').title()}: {V:.4e} AU³ ({pct:.2f}%)\n"
        
        steps += f"""
    TOTAL (to Hill Sphere): {total_V:.4e} AU³
    
    NOTE: Extended Hill zone contains 99%+ of domain volume
    but has marginal binding and transient population
    ══════════════════════════════════════════════════════════════════"""
        
        return volumes, steps
    
    def validate_model(self) -> Tuple[bool, list, str]:
        """Validate Solar Domain Model."""
        tests = []
        
        # Test 1: 5 zones defined
        tests.append({
            'name': '5 zones defined',
            'n_zones': len(self.zones),
            'passed': len(self.zones) == 5
        })
        
        # Test 2: Zones are contiguous
        zones_sorted = sorted(self.zones.values(), key=lambda x: x['inner'])
        contiguous = all(zones_sorted[i]['outer'] == zones_sorted[i+1]['inner'] 
                         for i in range(len(zones_sorted)-1))
        tests.append({
            'name': 'Zones are contiguous',
            'passed': contiguous
        })
        
        # Test 3: Neptune in planetary zone
        zone, _, _ = self.classify_distance(30)
        tests.append({
            'name': 'Neptune (30 AU) in planetary zone',
            'zone': zone,
            'passed': zone == 'planetary'
        })
        
        # Test 4: Binding energy negative (bound)
        E, _ = self.compute_binding_energy(100)
        tests.append({
            'name': 'Binding energy negative (bound)',
            'E': E,
            'passed': E < 0
        })
        
        all_passed = all(t['passed'] for t in tests)
        
        summary = f"""SOLAR DOMAIN MODEL VALIDATION
════════════════════════════════════════════════════════════════════════════════
TEST RESULTS:
────────────────────────────────────────────────────────────────────────────────
1. 5 zones defined:                {'✓ PASS' if tests[0]['passed'] else '✗ FAIL'}
   {tests[0]['n_zones']} zones

2. Zones contiguous:               {'✓ PASS' if tests[1]['passed'] else '✗ FAIL'}

3. Neptune in planetary zone:      {'✓ PASS' if tests[2]['passed'] else '✗ FAIL'}
   Classified as: {tests[2]['zone']}

4. Binding energy < 0:             {'✓ PASS' if tests[3]['passed'] else '✗ FAIL'}
   E = {tests[3]['E']:.4e} J

────────────────────────────────────────────────────────────────────────────────
SUMMARY: {sum(t['passed'] for t in tests)}/{len(tests)} tests passed
────────────────────────────────────────────────────────────────────────────────
{'ALL TESTS PASSED ✓' if all_passed else 'SOME TESTS FAILED ✗'}
════════════════════════════════════════════════════════════════════════════════
"""
        return all_passed, tests, summary


# Global Solar Domain Model instance
SOLAR_DOMAIN_MODEL = SolarDomainModel()


