class GravitationalTimeDilationModel:
    """
    Gravitational Time Dilation Model - GR Time Effects
    
    Models the slowing of time in gravitational fields, essential for
    understanding dynamics near SMBHs and compact objects.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    t' = t₀ × √(1 - 2GM/(rc²))
    
    Where:
        t' : Proper time experienced in gravitational field (s)
        t₀ : Coordinate time in flat spacetime (s)
        G : Gravitational constant (6.674 × 10⁻¹¹ m³ kg⁻¹ s⁻²)
        M : Mass of gravitating body (kg)
        r : Distance from center of mass (m)
        c : Speed of light (2.998 × 10⁸ m/s)
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Time runs slower in stronger gravitational fields
    - At r = r_s (Schwarzschild radius): time stops (event horizon)
    - Far from mass: t' → t₀ (flat spacetime)
    
    APPLICATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - GPS satellite corrections (~45 μs/day faster)
    - Black hole accretion disk observations
    - Gravitational wave source timing
    - SMBH dynamics near event horizon
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant (m³ kg⁻¹ s⁻²)
        self.c = 2.998e8           # Speed of light (m/s)
        self.M_sun = 1.989e30      # Solar mass (kg)
        
    def compute_time_dilation(self, t0: float, M: float, r: float) -> Tuple[float, str]:
        """
        Compute proper time in gravitational field.
        
        Args:
            t0: Coordinate time (s)
            M: Mass of gravitating body (kg)
            r: Distance from center (m)
            
        Returns:
            t_proper: Proper time experienced (s)
            steps: Calculation explanation
        """
        import math
        
        # Schwarzschild radius
        r_s = 2 * self.G * M / self.c**2
        
        if r <= r_s:
            raise ValueError(f"r = {r} m ≤ r_s = {r_s} m: inside event horizon")
        
        # Time dilation factor
        gamma = math.sqrt(1 - r_s / r)
        t_proper = t0 * gamma
        
        steps = f"""Gravitational Time Dilation:
  
  t' = t₀ × √(1 - 2GM/(rc²)) = t₀ × √(1 - r_s/r)
  
  Parameters:
    M = {M:.4e} kg = {M/self.M_sun:.2f} M_☉
    r = {r:.4e} m
    t₀ = {t0:.6f} s
    
  Schwarzschild radius:
    r_s = 2GM/c² = {r_s:.4e} m
    r/r_s = {r/r_s:.2f}
  
  Time dilation factor:
    γ = √(1 - r_s/r) = √(1 - {r_s/r:.6f}) = {gamma:.6f}
  
  Result:
    t' = {t0:.6f} × {gamma:.6f} = {t_proper:.6f} s
    
  Time runs {(1-gamma)*100:.4f}% slower at r = {r:.4e} m
"""
        return t_proper, steps
    
    def compute_dilation_factor(self, M: float, r: float) -> Tuple[float, str]:
        """
        Compute time dilation factor γ = √(1 - r_s/r).
        
        Args:
            M: Mass (kg)
            r: Distance (m)
            
        Returns:
            gamma: Time dilation factor [0, 1]
            steps: Calculation explanation
        """
        import math
        
        r_s = 2 * self.G * M / self.c**2
        
        if r <= r_s:
            gamma = 0.0
            steps = f"r ≤ r_s = {r_s:.4e} m: γ = 0 (event horizon or interior)"
        else:
            gamma = math.sqrt(1 - r_s / r)
            steps = f"""Time Dilation Factor:
  
  γ = √(1 - r_s/r)
  r_s = 2GM/c² = {r_s:.4e} m
  γ = √(1 - {r_s:.4e}/{r:.4e}) = {gamma:.6f}
  
  Clock at r runs at {gamma*100:.4f}% of rate at infinity.
"""
        return gamma, steps
    
    def compute_GPS_correction(self) -> Tuple[float, str]:
        """
        Compute GPS time dilation correction.
        
        Returns:
            delta_t: Time gained per day (s)
            steps: Calculation explanation
        """
        import math
        
        M_earth = 5.972e24      # kg
        r_surface = 6.371e6     # m (Earth surface)
        r_GPS = 26.56e6         # m (GPS orbital radius)
        day_seconds = 86400     # s
        
        gamma_surface = math.sqrt(1 - 2*self.G*M_earth/(r_surface*self.c**2))
        gamma_GPS = math.sqrt(1 - 2*self.G*M_earth/(r_GPS*self.c**2))
        
        # GPS clock runs faster due to weaker gravity
        delta_gamma = gamma_GPS - gamma_surface
        delta_t = delta_gamma * day_seconds
        
        # Convert to microseconds
        delta_t_us = delta_t * 1e6
        
        steps = f"""GPS Gravitational Time Correction:
  
  Earth surface: r = {r_surface:.4e} m, γ = {gamma_surface:.10f}
  GPS orbit: r = {r_GPS:.4e} m, γ = {gamma_GPS:.10f}
  
  Δγ = γ_GPS - γ_surface = {delta_gamma:.4e}
  Δt/day = Δγ × 86400 s = {delta_t_us:.2f} μs
  
  GPS clocks run ~{delta_t_us:.1f} μs faster per day (gravity only).
  (Special relativistic correction: -7.2 μs/day)
  Net correction: ~38 μs/day
"""
        return delta_t_us, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Gravitational Time Dilation Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Far from mass, γ → 1
        gamma_far, _ = self.compute_dilation_factor(self.M_sun, 1e15)
        t1 = abs(gamma_far - 1.0) < 1e-6
        tests.append(f"Test 1: γ(r=1e15 m) = {gamma_far:.8f} ≈ 1: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: At 10 r_s, γ ≈ 0.949
        M_test = 10 * self.M_sun
        r_s = 2 * self.G * M_test / self.c**2
        gamma_10rs, _ = self.compute_dilation_factor(M_test, 10 * r_s)
        t2 = abs(gamma_10rs - math.sqrt(0.9)) < 0.01
        tests.append(f"Test 2: γ(r=10 r_s) = {gamma_10rs:.4f} ≈ √0.9 = 0.949: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: GPS correction in correct range (38-50 μs)
        delta_GPS, _ = self.compute_GPS_correction()
        t3 = 40 < delta_GPS < 50
        tests.append(f"Test 3: GPS correction = {delta_GPS:.2f} μs ∈ [40, 50]: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Time dilation computation
        t_proper, _ = self.compute_time_dilation(1.0, self.M_sun, 1e9)
        t4 = 0.99 < t_proper < 1.0
        tests.append(f"Test 4: t'(1s, M_☉, 1e9 m) = {t_proper:.8f} s < 1: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"GravitationalTimeDilationModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class GravitationalRedshiftModel:
    """
    Gravitational Redshift Model - Light Escaping Gravitational Wells
    
    Quantifies the redshift of light emitted near massive objects,
    observable in SMBH accretion disks and neutron stars.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    z = √[(1 - 2GM/(r₀c²)) / (1 - 2GM/(rc²))] - 1
    
    For emission at r₀ observed at r >> r_s:
    
    z ≈ 1/√(1 - 2GM/(r₀c²)) - 1
    
    Where:
        z : Gravitational redshift factor
        r₀ : Radius of emission (m)
        r : Radius of observation (m)
        G, M, c : As defined above
    
    PHYSICAL INTERPRETATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Photons lose energy climbing out of gravitational well
    - λ_observed > λ_emitted (redshift)
    - At event horizon: z → ∞ (infinite redshift)
    
    OBSERVATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Fe Kα line at 6.4 keV from AGN accretion disks
    - White dwarf surface: z ~ 10⁻⁴
    - Neutron star: z ~ 0.2-0.4
    - ISCO of black hole: z ~ 0.5-2
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant
        self.c = 2.998e8           # Speed of light
        self.M_sun = 1.989e30      # Solar mass
        
    def compute_redshift(self, M: float, r0: float, r_obs: float = None) -> Tuple[float, str]:
        """
        Compute gravitational redshift.
        
        Args:
            M: Mass of gravitating body (kg)
            r0: Emission radius (m)
            r_obs: Observation radius (m), default = infinity
            
        Returns:
            z: Redshift factor
            steps: Calculation explanation
        """
        import math
        
        r_s = 2 * self.G * M / self.c**2
        
        if r0 <= r_s:
            raise ValueError(f"r0 = {r0} m ≤ r_s = {r_s} m: inside event horizon")
        
        term_emit = 1 - r_s / r0
        
        if r_obs is None or r_obs > 1e20:
            # Observer at infinity
            z = 1 / math.sqrt(term_emit) - 1
            obs_location = "infinity"
        else:
            if r_obs <= r_s:
                raise ValueError("Observer inside event horizon")
            term_obs = 1 - r_s / r_obs
            z = math.sqrt(term_obs / term_emit) - 1
            obs_location = f"{r_obs:.4e} m"
        
        steps = f"""Gravitational Redshift:
  
  z = √[(1 - r_s/r_obs) / (1 - r_s/r₀)] - 1
  
  Parameters:
    M = {M:.4e} kg = {M/self.M_sun:.2f} M_☉
    r_s = 2GM/c² = {r_s:.4e} m
    r₀ (emission) = {r0:.4e} m = {r0/r_s:.2f} r_s
    r_obs = {obs_location}
  
  Calculation:
    1 - r_s/r₀ = {term_emit:.6f}
  
  Result:
    z = {z:.6f}
    
  Wavelength stretching: λ_obs/λ_emit = 1 + z = {1 + z:.6f}
  Energy loss: E_obs/E_emit = 1/(1+z) = {1/(1+z):.6f}
"""
        return z, steps
    
    def compute_wavelength_shift(self, lambda_emit: float, z: float) -> Tuple[float, str]:
        """
        Compute observed wavelength from emitted and redshift.
        
        Args:
            lambda_emit: Emitted wavelength (m or any unit)
            z: Redshift factor
            
        Returns:
            lambda_obs: Observed wavelength (same units)
            steps: Calculation explanation
        """
        lambda_obs = lambda_emit * (1 + z)
        
        steps = f"""Wavelength Shift:
  
  λ_obs = λ_emit × (1 + z)
  λ_obs = {lambda_emit:.4e} × (1 + {z:.6f})
  λ_obs = {lambda_obs:.4e}
  
  Shift: Δλ = {lambda_obs - lambda_emit:.4e} ({z*100:.4f}% redshift)
"""
        return lambda_obs, steps
    
    def compute_ISCO_redshift(self, M: float, a: float = 0) -> Tuple[float, str]:
        """
        Compute redshift from Innermost Stable Circular Orbit (ISCO).
        
        Args:
            M: Black hole mass (kg)
            a: Dimensionless spin parameter [0, 1)
            
        Returns:
            z: Redshift from ISCO
            steps: Calculation explanation
        """
        import math
        
        r_s = 2 * self.G * M / self.c**2
        
        # ISCO radius (Schwarzschild: r_ISCO = 3 r_s)
        if a == 0:
            r_ISCO = 3 * r_s
            spin_type = "Schwarzschild (a=0)"
        else:
            # Kerr: r_ISCO = r_s × f(a), prograde
            Z1 = 1 + (1 - a**2)**(1/3) * ((1 + a)**(1/3) + (1 - a)**(1/3))
            Z2 = math.sqrt(3 * a**2 + Z1**2)
            r_ISCO = (r_s / 2) * (3 + Z2 - math.sqrt((3 - Z1)*(3 + Z1 + 2*Z2)))
            spin_type = f"Kerr (a={a})"
        
        z, _ = self.compute_redshift(M, r_ISCO)
        
        steps = f"""ISCO Redshift ({spin_type}):
  
  r_s = {r_s:.4e} m
  r_ISCO = {r_ISCO:.4e} m = {r_ISCO/r_s:.2f} r_s
  
  z(ISCO) = {z:.6f}
  
  This is the maximum stable redshift before plunge.
"""
        return z, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Gravitational Redshift Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: z → 0 far from mass
        z_far, _ = self.compute_redshift(self.M_sun, 1e15)
        t1 = abs(z_far) < 1e-6
        tests.append(f"Test 1: z(r=1e15 m) = {z_far:.2e} ≈ 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: z at 3 r_s (ISCO) for Schwarzschild ≈ 0.15-0.3
        M_test = 10 * self.M_sun
        z_ISCO, _ = self.compute_ISCO_redshift(M_test, 0)
        t2 = 0.1 < z_ISCO < 0.5
        tests.append(f"Test 2: z(ISCO, a=0) = {z_ISCO:.4f} ∈ [0.1, 0.5]: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Wavelength shift calculation
        lambda_obs, _ = self.compute_wavelength_shift(500e-9, 0.5)
        t3 = abs(lambda_obs - 750e-9) < 1e-12
        tests.append(f"Test 3: λ_obs(500nm, z=0.5) = {lambda_obs*1e9:.0f} nm = 750: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Higher spin → prograde ISCO closer → higher redshift (deeper potential)
        z_spin, _ = self.compute_ISCO_redshift(M_test, 0.9)
        t4 = z_spin > z_ISCO  # Closer ISCO means higher z (deeper gravitational well)
        tests.append(f"Test 4: z(ISCO, a=0.9) = {z_spin:.4f} > z(a=0) = {z_ISCO:.4f}: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"GravitationalRedshiftModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class TidalForceModel:
    """
    Tidal Force Model - Differential Gravity Effects
    
    Models the differential gravitational forces that can tear apart
    objects (spaghettification), critical for TDE physics.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    F_tidal = 2GMmd / r³
    
    Where:
        F_tidal : Tidal force (N)
        G : Gravitational constant
        M : Mass of primary (kg)
        m : Mass of secondary/test object (kg)
        d : Size of object along radial direction (m)
        r : Distance from primary center (m)
    
    TIDAL DISRUPTION RADIUS:
    ─────────────────────────────────────────────────────────────────────────────
    
    r_T ≈ R_* × (M_BH / M_*)^(1/3)
    
    Where:
        R_* : Stellar radius
        M_* : Stellar mass
        M_BH : Black hole mass
    
    For Sun disrupted by 10⁶ M_☉ SMBH:
        r_T ≈ 7 × 10¹⁰ m ≈ 0.5 AU
    
    APPLICATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Tidal Disruption Events (TDEs)
    - Roche limit calculations
    - Binary star evolution
    - Planetary ring formation
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.G = 6.674e-11         # Gravitational constant
        self.c = 2.998e8           # Speed of light
        self.M_sun = 1.989e30      # Solar mass
        self.R_sun = 6.96e8        # Solar radius (m)
        
    def compute_tidal_force(self, M: float, m: float, d: float, r: float) -> Tuple[float, str]:
        """
        Compute tidal force on extended object.
        
        Args:
            M: Primary mass (kg)
            m: Secondary/test object mass (kg)
            d: Object size along radial direction (m)
            r: Distance from primary center (m)
            
        Returns:
            F_tidal: Tidal force (N)
            steps: Calculation explanation
        """
        F_tidal = 2 * self.G * M * m * d / r**3
        
        # Compare to object's self-gravity
        g_self = self.G * m / d**2 if d > 0 else 0
        
        steps = f"""Tidal Force Calculation:
  
  F_tidal = 2GMmd / r³
  
  Parameters:
    M (primary) = {M:.4e} kg
    m (secondary) = {m:.4e} kg
    d (size) = {d:.4e} m
    r (distance) = {r:.4e} m
  
  Result:
    F_tidal = 2 × {self.G:.4e} × {M:.4e} × {m:.4e} × {d:.4e} / {r:.4e}³
    F_tidal = {F_tidal:.4e} N
  
  For comparison:
    Object's self-gravity: Gm/d² ~ {g_self:.4e} m/s²
    Tidal acceleration: F_tidal/m = {F_tidal/m if m > 0 else 0:.4e} m/s²
"""
        return F_tidal, steps
    
    def compute_tidal_tensor_component(self, M: float, r: float) -> Tuple[float, str]:
        """
        Compute tidal tensor eigenvalue (radial stretching).
        
        R_rr = 2GM/r³ (in geometrized units, restored: 2GM/(c²r³))
        
        Args:
            M: Primary mass (kg)
            r: Distance (m)
            
        Returns:
            R_rr: Tidal tensor component (s⁻²)
            steps: Calculation explanation
        """
        R_rr = 2 * self.G * M / r**3
        
        steps = f"""Tidal Tensor (Radial Component):
  
  R_rr = 2GM/r³
  R_rr = 2 × {self.G:.4e} × {M:.4e} / {r:.4e}³
  R_rr = {R_rr:.4e} s⁻²
  
  This represents the differential acceleration per unit length.
  Objects are stretched radially and compressed tangentially.
"""
        return R_rr, steps
    
    def compute_disruption_radius(self, M_BH: float, M_star: float = None, 
                                   R_star: float = None) -> Tuple[float, str]:
        """
        Compute tidal disruption radius.
        
        Args:
            M_BH: Black hole mass (kg)
            M_star: Stellar mass (kg), default = M_sun
            R_star: Stellar radius (m), default = R_sun
            
        Returns:
            r_T: Tidal disruption radius (m)
            steps: Calculation explanation
        """
        if M_star is None:
            M_star = self.M_sun
        if R_star is None:
            R_star = self.R_sun
            
        # r_T = R_* × (M_BH / M_*)^(1/3)
        r_T = R_star * (M_BH / M_star) ** (1/3)
        
        # Compare to Schwarzschild radius
        r_s = 2 * self.G * M_BH / self.c**2
        
        # In AU
        r_T_AU = r_T / 1.496e11
        
        steps = f"""Tidal Disruption Radius:
  
  r_T = R_* × (M_BH / M_*)^(1/3)
  
  Parameters:
    M_BH = {M_BH:.4e} kg = {M_BH/self.M_sun:.2e} M_☉
    M_* = {M_star:.4e} kg = {M_star/self.M_sun:.2f} M_☉
    R_* = {R_star:.4e} m = {R_star/self.R_sun:.2f} R_☉
  
  Result:
    r_T = {R_star:.4e} × ({M_BH/M_star:.4e})^(1/3)
    r_T = {r_T:.4e} m = {r_T_AU:.4f} AU
  
  Schwarzschild radius:
    r_s = {r_s:.4e} m
    r_T/r_s = {r_T/r_s:.2f}
    
  {'Star disrupted OUTSIDE event horizon (observable TDE)' if r_T > r_s else 'Star swallowed whole (no flare)'}
"""
        return r_T, steps
    
    def compute_spaghettification_distance(self, M_BH: float, human_height: float = 1.8,
                                           human_mass: float = 70) -> Tuple[float, str]:
        """
        Compute distance where tidal forces would tear apart a human.
        
        The human survives when tidal acceleration < ~10g (100 m/s²).
        
        Args:
            M_BH: Black hole mass (kg)
            human_height: Height (m)
            human_mass: Mass (kg)
            
        Returns:
            r_spaghetti: Distance where tidal force becomes lethal (m)
            steps: Calculation explanation
        """
        import math
        
        # Tidal acceleration: a_tidal = 2GM×d/r³
        # Set a_tidal = 100 m/s² (10g tolerance)
        a_limit = 100  # m/s²
        d = human_height
        
        # r³ = 2GM×d / a_limit
        r_spaghetti = (2 * self.G * M_BH * d / a_limit) ** (1/3)
        
        r_s = 2 * self.G * M_BH / self.c**2
        
        steps = f"""Spaghettification Distance (10g limit):
  
  Tidal acceleration limit: a_tidal = 100 m/s² (10g)
  Human height: d = {human_height} m
  
  r³ = 2GM×d / a_limit
  r = (2 × {self.G:.4e} × {M_BH:.4e} × {d} / {a_limit})^(1/3)
  r = {r_spaghetti:.4e} m
  
  r_s = {r_s:.4e} m
  r_spaghetti/r_s = {r_spaghetti/r_s:.2f}
  
  {'Spaghettification occurs OUTSIDE event horizon' if r_spaghetti > r_s else 'Safe past event horizon (tidal forces manageable)'}
  
  For M_BH > ~10⁵ M_☉, humans cross horizon before spaghettification.
"""
        return r_spaghetti, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Tidal Force Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Tidal force scales as 1/r³
        F1, _ = self.compute_tidal_force(self.M_sun, 1e10, 1e6, 1e10)
        F2, _ = self.compute_tidal_force(self.M_sun, 1e10, 1e6, 2e10)
        ratio = F1 / F2
        t1 = abs(ratio - 8.0) < 0.1  # (2)³ = 8
        tests.append(f"Test 1: F_tidal(r) / F_tidal(2r) = {ratio:.2f} ≈ 8: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Sun TDE by 10⁶ M_☉ SMBH: r_T ~ 0.5 AU
        r_T, _ = self.compute_disruption_radius(1e6 * self.M_sun)
        r_T_AU = r_T / 1.496e11
        t2 = 0.3 < r_T_AU < 1.0
        tests.append(f"Test 2: r_T(10⁶ M_☉) = {r_T_AU:.2f} AU ∈ [0.3, 1.0]: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Tidal tensor positive (stretching)
        R_rr, _ = self.compute_tidal_tensor_component(self.M_sun, 1e9)
        t3 = R_rr > 0
        tests.append(f"Test 3: R_rr = {R_rr:.4e} > 0 (stretching): {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Spaghettification outside horizon for stellar BH
        r_sp, _ = self.compute_spaghettification_distance(10 * self.M_sun)
        r_s = 2 * self.G * 10 * self.M_sun / self.c**2
        t4 = r_sp > r_s
        tests.append(f"Test 4: r_spaghetti = {r_sp:.4e} > r_s = {r_s:.4e}: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"TidalForceModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


# Global SM Gravity Model instances
GRAVITATIONAL_TIME_DILATION_MODEL = GravitationalTimeDilationModel()
GRAVITATIONAL_REDSHIFT_MODEL = GravitationalRedshiftModel()
TIDAL_FORCE_MODEL = TidalForceModel()


