class NavierStokesVortexModel:
    """
    Navier-Stokes Vortex Model - Fluid Dynamics in Astrophysical Systems
    
    Models vortex dynamics in accretion disks, stellar atmospheres,
    and interstellar medium using incompressible Navier-Stokes equations.
    
    KEY EQUATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Momentum (Navier-Stokes):
    ∂v/∂t + (v·∇)v = -∇P/ρ + ν∇²v + f
    
    Vorticity (curl of velocity):
    ω = ∇ × v
    
    Vorticity transport:
    ∂ω/∂t + (v·∇)ω = (ω·∇)v + ν∇²ω
    
    Where:
        v : Velocity field (m/s)
        P : Pressure (Pa)
        ρ : Density (kg/m³)
        ν : Kinematic viscosity (m²/s)
        ω : Vorticity (1/s)
        f : External forces
    
    APPLICATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Accretion disk turbulence (MRI-driven)
    - Stellar convection (granulation, supergranulation)
    - Planetary atmospheric vortices (Great Red Spot)
    - Interstellar turbulence cascade
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # Characteristic scales
        self.L_typical = 1e9         # Typical length scale (m, ~0.01 AU)
        self.V_typical = 1e5         # Typical velocity (m/s, 100 km/s)
        
    def compute_reynolds_number(self, L: float, V: float, nu: float) -> Tuple[float, str]:
        """
        Compute Reynolds number (turbulence indicator).
        
        Re = V × L / ν
        
        Args:
            L: Characteristic length (m)
            V: Characteristic velocity (m/s)
            nu: Kinematic viscosity (m²/s)
            
        Returns:
            Re: Reynolds number
            steps: Calculation explanation
        """
        Re = V * L / nu
        
        if Re < 1:
            regime = "Stokes flow (viscosity dominates)"
        elif Re < 2000:
            regime = "Laminar flow"
        elif Re < 4000:
            regime = "Transitional"
        else:
            regime = "Turbulent (inertia dominates)"
        
        steps = f"""Reynolds Number:
  
  Re = V × L / ν
  
  Parameters:
    L = {L:.4e} m
    V = {V:.4e} m/s
    ν = {nu:.4e} m²/s
  
  Result:
    Re = {Re:.4e}
    Regime: {regime}
    
  Astrophysical flows often have Re > 10¹⁰ (strongly turbulent).
"""
        return Re, steps
    
    def compute_vorticity_magnitude(self, V: float, L: float) -> Tuple[float, str]:
        """
        Estimate vorticity magnitude from velocity gradient.
        
        |ω| ~ V/L
        
        Args:
            V: Velocity scale (m/s)
            L: Length scale (m)
            
        Returns:
            omega: Vorticity magnitude (1/s)
            steps: Calculation explanation
        """
        omega = V / L
        period = 2 * 3.14159 / omega
        
        steps = f"""Vorticity Magnitude:
  
  |ω| ~ V/L (order of magnitude estimate)
  
  Parameters:
    V = {V:.4e} m/s
    L = {L:.4e} m
  
  Result:
    |ω| = {omega:.4e} s⁻¹
    Rotation period ≈ {period:.4e} s = {period/3600:.2f} hours
"""
        return omega, steps
    
    def compute_circulation(self, omega: float, A: float) -> Tuple[float, str]:
        """
        Compute circulation from vorticity (Stokes theorem).
        
        Γ = ∮ v·dl = ∫∫ ω·dA
        
        Args:
            omega: Vorticity (1/s)
            A: Area enclosed (m²)
            
        Returns:
            Gamma: Circulation (m²/s)
            steps: Calculation explanation
        """
        Gamma = omega * A
        
        steps = f"""Circulation (Stokes Theorem):
  
  Γ = ∫∫ ω·dA ≈ ω × A (uniform ω)
  
  Parameters:
    ω = {omega:.4e} s⁻¹
    A = {A:.4e} m²
  
  Result:
    Γ = {Gamma:.4e} m²/s
    
  Circulation is conserved in inviscid flow (Kelvin theorem).
"""
        return Gamma, steps
    
    def compute_kolmogorov_scale(self, nu: float, epsilon: float) -> Tuple[float, str]:
        """
        Compute Kolmogorov (dissipation) scale.
        
        η = (ν³/ε)^(1/4)
        
        Args:
            nu: Kinematic viscosity (m²/s)
            epsilon: Energy dissipation rate (m²/s³)
            
        Returns:
            eta: Kolmogorov scale (m)
            steps: Calculation explanation
        """
        eta = (nu**3 / epsilon)**(1/4)
        
        steps = f"""Kolmogorov (Dissipation) Scale:
  
  η = (ν³/ε)^(1/4)
  
  Parameters:
    ν = {nu:.4e} m²/s
    ε = {epsilon:.4e} m²/s³
  
  Result:
    η = {eta:.4e} m
    
  Below η, viscosity dissipates kinetic energy to heat.
  Energy cascades from large to small scales until η.
"""
        return eta, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Navier-Stokes Vortex Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Reynolds number scaling
        Re1, _ = self.compute_reynolds_number(1e6, 1e3, 1e-6)
        Re2, _ = self.compute_reynolds_number(1e6, 1e3, 1e-3)
        t1 = Re1 > Re2  # Lower viscosity → higher Re
        tests.append(f"Test 1: Re(ν=10⁻⁶) > Re(ν=10⁻³): {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Vorticity physical
        omega, _ = self.compute_vorticity_magnitude(1e5, 1e9)
        t2 = 1e-5 < omega < 1e-3
        tests.append(f"Test 2: ω(100km/s, 10⁹m) = {omega:.2e} ∈ [10⁻⁵, 10⁻³]: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Circulation conservation check
        Gamma, _ = self.compute_circulation(1e-4, 1e18)
        t3 = Gamma > 0
        tests.append(f"Test 3: Γ = {Gamma:.2e} m²/s > 0: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Kolmogorov scale physical
        eta, _ = self.compute_kolmogorov_scale(1e-6, 1e-3)
        t4 = 1e-6 < eta < 1e-2
        tests.append(f"Test 4: η = {eta:.2e} m ∈ [10⁻⁶, 10⁻²]: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"NavierStokesVortexModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class LangevinDynamicsModel:
    """
    Langevin Dynamics Model - Stochastic Differential Equations
    
    Models systems with deterministic drift plus random fluctuations,
    applicable to particle motion, spin evolution, and thermalization.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    dx/dt = -γx + √(2D) × ξ(t)
    
    Where:
        x : State variable
        γ : Damping coefficient (1/time)
        D : Diffusion coefficient
        ξ(t) : White noise (⟨ξ(t)ξ(t')⟩ = δ(t-t'))
    
    Fluctuation-Dissipation Theorem:
    D = γ k_B T / m (Einstein relation)
    
    SOLUTIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Mean: ⟨x(t)⟩ = x₀ × exp(-γt)
    
    Variance: Var[x(t)] = (D/γ) × (1 - exp(-2γt))
    
    Equilibrium: Var[x(∞)] = D/γ = k_B T/m
    
    APPLICATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Brownian motion in stellar atmospheres
    - Spin diffusion in magnetars
    - Particle thermalization in hot plasmas
    - Stochastic gravitational wave background
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        self.k_B = 1.381e-23       # Boltzmann constant (J/K)
        
    def compute_diffusion_coefficient(self, gamma: float, T: float, m: float) -> Tuple[float, str]:
        """
        Compute diffusion coefficient from Einstein relation.
        
        D = γ k_B T / m
        
        Args:
            gamma: Damping coefficient (1/s)
            T: Temperature (K)
            m: Mass (kg)
            
        Returns:
            D: Diffusion coefficient (m²/s)
            steps: Calculation explanation
        """
        D = gamma * self.k_B * T / m
        
        steps = f"""Diffusion Coefficient (Einstein Relation):
  
  D = γ k_B T / m
  
  Parameters:
    γ = {gamma:.4e} s⁻¹
    T = {T:.4e} K
    m = {m:.4e} kg
  
  Result:
    D = {D:.4e} m²/s
    
  This ensures thermal equilibrium: Var[x] = k_B T/m at t→∞.
"""
        return D, steps
    
    def compute_relaxation_time(self, gamma: float) -> Tuple[float, str]:
        """
        Compute relaxation time.
        
        τ = 1/γ
        
        Args:
            gamma: Damping coefficient (1/s)
            
        Returns:
            tau: Relaxation time (s)
            steps: Calculation explanation
        """
        tau = 1.0 / gamma
        
        steps = f"""Relaxation Time:
  
  τ = 1/γ
  
  Parameter:
    γ = {gamma:.4e} s⁻¹
  
  Result:
    τ = {tau:.4e} s
    
  After ~3τ, system reaches ~95% of equilibrium.
"""
        return tau, steps
    
    def compute_mean_evolution(self, x0: float, gamma: float, t: float) -> Tuple[float, str]:
        """
        Compute mean trajectory.
        
        ⟨x(t)⟩ = x₀ × exp(-γt)
        
        Args:
            x0: Initial value
            gamma: Damping coefficient (1/s)
            t: Time (s)
            
        Returns:
            x_mean: Mean value at time t
            steps: Calculation explanation
        """
        import math
        
        x_mean = x0 * math.exp(-gamma * t)
        
        steps = f"""Mean Trajectory:
  
  ⟨x(t)⟩ = x₀ × exp(-γt)
  
  Parameters:
    x₀ = {x0:.4e}
    γ = {gamma:.4e} s⁻¹
    t = {t:.4e} s
  
  Result:
    ⟨x(t)⟩ = {x_mean:.4e}
    Decay factor: exp(-γt) = {math.exp(-gamma*t):.4f}
"""
        return x_mean, steps
    
    def compute_variance_evolution(self, D: float, gamma: float, t: float) -> Tuple[float, str]:
        """
        Compute variance evolution.
        
        Var[x(t)] = (D/γ) × (1 - exp(-2γt))
        
        Args:
            D: Diffusion coefficient
            gamma: Damping coefficient (1/s)
            t: Time (s)
            
        Returns:
            var_x: Variance at time t
            steps: Calculation explanation
        """
        import math
        
        var_eq = D / gamma
        var_x = var_eq * (1 - math.exp(-2 * gamma * t))
        
        steps = f"""Variance Evolution:
  
  Var[x(t)] = (D/γ) × (1 - exp(-2γt))
  
  Parameters:
    D = {D:.4e}
    γ = {gamma:.4e} s⁻¹
    t = {t:.4e} s
  
  Result:
    Var_eq = D/γ = {var_eq:.4e}
    Var[x(t)] = {var_x:.4e}
    Fraction of equilibrium: {var_x/var_eq:.4f}
"""
        return var_x, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Langevin Dynamics Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: D satisfies dimensional analysis
        D, _ = self.compute_diffusion_coefficient(1e6, 1e7, 1.673e-27)
        t1 = D > 0
        tests.append(f"Test 1: D = {D:.2e} m²/s > 0: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Mean decays exponentially
        x_early, _ = self.compute_mean_evolution(1.0, 1.0, 0.5)
        x_late, _ = self.compute_mean_evolution(1.0, 1.0, 2.0)
        t2 = x_early > x_late
        tests.append(f"Test 2: ⟨x(0.5)⟩ > ⟨x(2)⟩: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Variance grows then saturates
        var_early, _ = self.compute_variance_evolution(1.0, 1.0, 0.5)
        var_late, _ = self.compute_variance_evolution(1.0, 1.0, 10.0)
        t3 = var_late > var_early and abs(var_late - 1.0) < 0.01  # D/γ = 1
        tests.append(f"Test 3: Var saturates at D/γ: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Relaxation time inverse of gamma
        tau, _ = self.compute_relaxation_time(0.1)
        t4 = abs(tau - 10.0) < 0.01
        tests.append(f"Test 4: τ(γ=0.1) = {tau} = 10s: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"LangevinDynamicsModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class BrainWaveSubharmonicModel:
    """
    Brainwave Subharmonic Model - Neural Resonance Patterns
    
    Models the relationship between brain wave frequencies and
    subharmonic resonances, connecting neuroscience to UQFF principles.
    
    KEY EQUATION:
    ─────────────────────────────────────────────────────────────────────────────
    
    f_sub = f_base / n (n = 1, 2, 3, ...)
    
    UQFF Connection:
    f_dT = 40 Hz (gamma band - conscious integration)
    
    BRAIN WAVE BANDS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Delta (δ): 0.5-4 Hz   - Deep sleep, healing
    Theta (θ): 4-8 Hz     - Meditation, memory
    Alpha (α): 8-13 Hz    - Relaxation, awareness
    Beta (β): 13-30 Hz    - Active thinking, focus
    Gamma (γ): 30-100 Hz  - Higher cognition, binding
    
    SUBHARMONIC RELATIONSHIPS:
    ─────────────────────────────────────────────────────────────────────────────
    
    Base: f_dT = 40 Hz (gamma)
    1st subharmonic: 40/2 = 20 Hz (beta)
    2nd subharmonic: 40/3 = 13.3 Hz (alpha/beta boundary)
    3rd subharmonic: 40/4 = 10 Hz (alpha)
    4th subharmonic: 40/5 = 8 Hz (theta/alpha boundary)
    ...
    10th subharmonic: 40/10 = 4 Hz (theta/delta boundary)
    
    IMPLICATIONS:
    ─────────────────────────────────────────────────────────────────────────────
    
    The UQFF temporal frequency f_dT = 40 Hz generates all brain wave bands
    through subharmonic division, suggesting deep connection between
    consciousness and quantum field coherence.
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # UQFF base frequency
        self.f_dT = 40.0           # Hz
        self.A2 = 3.102             # V (UQFF amplitude)
        self.dA = 5.205             # V (amplitude stability)
        
        # Brain wave band boundaries
        self.bands = {
            "delta": (0.5, 4),
            "theta": (4, 8),
            "alpha": (8, 13),
            "beta": (13, 30),
            "gamma": (30, 100)
        }
        
    def compute_subharmonic(self, f_base: float, n: int) -> Tuple[float, str]:
        """
        Compute nth subharmonic frequency.
        
        Args:
            f_base: Base frequency (Hz)
            n: Subharmonic order (1 = fundamental)
            
        Returns:
            f_sub: Subharmonic frequency (Hz)
            steps: Calculation explanation
        """
        if n < 1:
            n = 1
        f_sub = f_base / n
        
        # Classify band
        band = "unknown"
        for name, (f_low, f_high) in self.bands.items():
            if f_low <= f_sub < f_high:
                band = name
                break
        
        steps = f"""Subharmonic Frequency:
  
  f_sub = f_base / n
  
  Parameters:
    f_base = {f_base} Hz
    n = {n}
  
  Result:
    f_sub = {f_sub:.2f} Hz
    Brain wave band: {band}
"""
        return f_sub, steps
    
    def compute_band_subharmonics(self, band_name: str) -> Tuple[List[int], str]:
        """
        Find which subharmonics fall in a given band.
        
        Args:
            band_name: Name of brain wave band
            
        Returns:
            harmonics: List of subharmonic orders in band
            steps: Calculation explanation
        """
        if band_name.lower() not in self.bands:
            return [], f"Unknown band: {band_name}"
        
        f_low, f_high = self.bands[band_name.lower()]
        harmonics = []
        
        for n in range(1, 100):
            f_sub = self.f_dT / n
            if f_sub < f_low:
                break
            if f_low <= f_sub < f_high:
                harmonics.append(n)
        
        steps = f"""Subharmonics in {band_name} Band:
  
  Band range: {f_low}-{f_high} Hz
  Base: f_dT = {self.f_dT} Hz
  
  Subharmonic orders in band: {harmonics}
  Frequencies: {[round(self.f_dT/n, 2) for n in harmonics]} Hz
"""
        return harmonics, steps
    
    def compute_coherence_amplitude(self, n: int) -> Tuple[float, str]:
        """
        Compute expected amplitude at nth subharmonic.
        
        A_n = A₂ × (1/n)^0.5 (amplitude scaling)
        
        Args:
            n: Subharmonic order
            
        Returns:
            A_n: Amplitude at nth subharmonic (V)
            steps: Calculation explanation
        """
        import math
        
        if n < 1:
            n = 1
        A_n = self.A2 / math.sqrt(n)
        
        steps = f"""Subharmonic Amplitude:
  
  A_n = A₂ × n^(-1/2)
  
  Parameters:
    A₂ = {self.A2} V (UQFF reference)
    n = {n}
  
  Result:
    A_n = {A_n:.4f} V
    f_n = {self.f_dT/n:.2f} Hz
"""
        return A_n, steps
    
    def compute_resonance_quality(self, f_measured: float, 
                                   f_theoretical: float) -> Tuple[float, str]:
        """
        Compute resonance quality (closeness to theoretical).
        
        Q = 1 - |f_meas - f_theo| / f_theo
        
        Args:
            f_measured: Measured frequency (Hz)
            f_theoretical: Theoretical frequency (Hz)
            
        Returns:
            Q: Quality factor [0, 1]
            steps: Calculation explanation
        """
        deviation = abs(f_measured - f_theoretical)
        Q = max(0, 1 - deviation / f_theoretical)
        
        steps = f"""Resonance Quality:
  
  Q = 1 - |f_meas - f_theo| / f_theo
  
  Parameters:
    f_measured = {f_measured} Hz
    f_theoretical = {f_theoretical} Hz
  
  Result:
    Deviation = {deviation:.4f} Hz
    Q = {Q:.4f}
    
  Q > 0.95: Strong resonance
  Q > 0.9: Good resonance
  Q < 0.8: Weak or no resonance
"""
        return Q, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate Brainwave Subharmonic Model."""
        tests = []
        all_passed = True
        
        # Test 1: 10 Hz is alpha band (n=4)
        f_4, _ = self.compute_subharmonic(40, 4)
        t1 = 8 <= f_4 <= 13
        tests.append(f"Test 1: f(n=4) = {f_4} Hz ∈ α-band [8,13]: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Alpha band has subharmonics
        alpha_h, _ = self.compute_band_subharmonics("alpha")
        t2 = len(alpha_h) >= 1
        tests.append(f"Test 2: α-band has {len(alpha_h)} subharmonics: {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: Amplitude decreases with n
        A_1, _ = self.compute_coherence_amplitude(1)
        A_10, _ = self.compute_coherence_amplitude(10)
        t3 = A_1 > A_10
        tests.append(f"Test 3: A(n=1) > A(n=10): {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: Perfect match gives Q=1
        Q, _ = self.compute_resonance_quality(10.0, 10.0)
        t4 = abs(Q - 1.0) < 0.001
        tests.append(f"Test 4: Q(10Hz, 10Hz) = {Q:.4f} ≈ 1: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"BrainWaveSubharmonicModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


class QScopeDataModel:
    """
    QScope Data Model - UQFF Measurement Instrumentation
    
    Models the data acquisition and processing for quantum field
    measurements using the QScope methodology.
    
    KEY PARAMETERS (from UQFF):
    ─────────────────────────────────────────────────────────────────────────────
    
    f_hole = 1.2 THz (quantum hole frequency)
    A₂ = 3.102 V (reference amplitude)
    dA = 5.205 V (amplitude differential)
    f_dT = 40 Hz (temporal sampling frequency)
    
    MEASUREMENT CHAIN:
    ─────────────────────────────────────────────────────────────────────────────
    
    1. Field Detection: Antenna couples to quantum field oscillations
    2. Amplification: Low-noise amplifier with gain G
    3. Filtering: Bandpass around f_hole
    4. Digitization: ADC at sample rate f_s >> f_dT
    5. Processing: FFT, correlation, pattern matching
    
    DATA PRODUCTS:
    ─────────────────────────────────────────────────────────────────────────────
    
    - Field amplitude time series: A(t)
    - Power spectrum: P(f)
    - Phase coherence: φ(t)
    - Superconductive measure: SC_m from field integrals
    
    ©2025 Daniel T. Murphy - All Rights Reserved
    """
    
    def __init__(self):
        # UQFF reference values
        self.f_hole = 1.2e12       # Hz (1.2 THz)
        self.A2 = 3.102             # V
        self.dA = 5.205             # V
        self.f_dT = 40.0            # Hz
        
        # Instrument parameters
        self.noise_floor = 1e-9     # V/√Hz
        self.sample_rate = 1e9      # Hz (1 GHz for THz detection)
        self.ADC_bits = 16          # bits
        
    def compute_nyquist_requirement(self, f_max: float) -> Tuple[float, str]:
        """
        Compute minimum sample rate (Nyquist).
        
        f_s >= 2 × f_max
        
        Args:
            f_max: Maximum frequency of interest (Hz)
            
        Returns:
            f_s_min: Minimum sample rate (Hz)
            steps: Calculation explanation
        """
        f_s_min = 2 * f_max
        
        steps = f"""Nyquist Sampling Requirement:
  
  f_s >= 2 × f_max
  
  For f_max = {f_max:.4e} Hz:
    f_s_min = {f_s_min:.4e} Hz = {f_s_min/1e9:.1f} GHz
    
  Current sample rate: {self.sample_rate:.4e} Hz
  {'ADEQUATE' if self.sample_rate >= f_s_min else 'INSUFFICIENT'}
"""
        return f_s_min, steps
    
    def compute_frequency_resolution(self, T: float) -> Tuple[float, str]:
        """
        Compute frequency resolution from observation time.
        
        Δf = 1/T
        
        Args:
            T: Observation time (s)
            
        Returns:
            delta_f: Frequency resolution (Hz)
            steps: Calculation explanation
        """
        delta_f = 1.0 / T
        
        steps = f"""Frequency Resolution:
  
  Δf = 1/T
  
  For T = {T} s:
    Δf = {delta_f:.4e} Hz
    
  Number of frequency bins up to f_hole:
    N_bins = f_hole / Δf = {self.f_hole / delta_f:.0f}
"""
        return delta_f, steps
    
    def compute_SNR(self, signal_amplitude: float, bandwidth: float) -> Tuple[float, str]:
        """
        Compute signal-to-noise ratio.
        
        SNR = A_signal / (noise_floor × √bandwidth)
        
        Args:
            signal_amplitude: RMS signal level (V)
            bandwidth: Measurement bandwidth (Hz)
            
        Returns:
            SNR: Signal-to-noise ratio
            steps: Calculation explanation
        """
        import math
        
        noise_rms = self.noise_floor * math.sqrt(bandwidth)
        SNR = signal_amplitude / noise_rms
        SNR_dB = 20 * math.log10(SNR) if SNR > 0 else float('-inf')
        
        steps = f"""Signal-to-Noise Ratio:
  
  SNR = A_signal / (noise_floor × √BW)
  
  Parameters:
    A_signal = {signal_amplitude:.4e} V
    Noise floor = {self.noise_floor:.4e} V/√Hz
    Bandwidth = {bandwidth:.4e} Hz
  
  Result:
    Noise RMS = {noise_rms:.4e} V
    SNR = {SNR:.2f}
    SNR = {SNR_dB:.1f} dB
"""
        return SNR, steps
    
    def compute_ADC_dynamic_range(self) -> Tuple[float, str]:
        """
        Compute ADC dynamic range.
        
        DR = 6.02 × N_bits + 1.76 dB
        
        Returns:
            DR: Dynamic range (dB)
            steps: Calculation explanation
        """
        DR = 6.02 * self.ADC_bits + 1.76
        
        steps = f"""ADC Dynamic Range:
  
  DR = 6.02 × N_bits + 1.76 dB
  
  For {self.ADC_bits}-bit ADC:
    DR = 6.02 × {self.ADC_bits} + 1.76
    DR = {DR:.1f} dB
    
  This corresponds to {2**self.ADC_bits} quantization levels.
  Maximum detectable signal ratio: {10**(DR/20):.0f}:1
"""
        return DR, steps
    
    def compute_integration_time(self, target_SNR: float, 
                                   signal_amplitude: float,
                                   bandwidth: float) -> Tuple[float, str]:
        """
        Compute required integration time for target SNR.
        
        SNR improves as √N (N = number of averages)
        T_int = (target_SNR / SNR_single)² × T_single
        
        Args:
            target_SNR: Desired SNR
            signal_amplitude: Signal level (V)
            bandwidth: Bandwidth (Hz)
            
        Returns:
            T_int: Integration time (s)
            steps: Calculation explanation
        """
        import math
        
        SNR_single, _ = self.compute_SNR(signal_amplitude, bandwidth)
        T_single = 1.0 / bandwidth  # Single measurement time
        
        if SNR_single >= target_SNR:
            T_int = T_single
        else:
            ratio = target_SNR / SNR_single
            T_int = ratio**2 * T_single
        
        steps = f"""Integration Time for Target SNR:
  
  T_int = (SNR_target / SNR_single)² × T_single
  
  Parameters:
    SNR_target = {target_SNR}
    SNR_single = {SNR_single:.2f}
    T_single = 1/BW = {T_single:.4e} s
  
  Result:
    T_int = {T_int:.4e} s = {T_int*1e3:.2f} ms
"""
        return T_int, steps
    
    def validate_model(self) -> Tuple[bool, List[str], str]:
        """Validate QScope Data Model."""
        import math
        tests = []
        all_passed = True
        
        # Test 1: Nyquist for 1.2 THz
        f_s_min, _ = self.compute_nyquist_requirement(self.f_hole)
        t1 = abs(f_s_min - 2.4e12) < 1e10
        tests.append(f"Test 1: f_s_min(1.2THz) = {f_s_min:.2e} ≈ 2.4 THz: {'PASS' if t1 else 'FAIL'}")
        all_passed &= t1
        
        # Test 2: Resolution improves with time
        df_short, _ = self.compute_frequency_resolution(0.1)
        df_long, _ = self.compute_frequency_resolution(1.0)
        t2 = df_short > df_long
        tests.append(f"Test 2: Δf(0.1s) > Δf(1s): {'PASS' if t2 else 'FAIL'}")
        all_passed &= t2
        
        # Test 3: SNR is positive for reasonable signal
        SNR, _ = self.compute_SNR(self.A2, 1e6)
        t3 = SNR > 1
        tests.append(f"Test 3: SNR(A₂) = {SNR:.0f} > 1: {'PASS' if t3 else 'FAIL'}")
        all_passed &= t3
        
        # Test 4: 16-bit ADC has ~98 dB range
        DR, _ = self.compute_ADC_dynamic_range()
        t4 = 96 < DR < 100
        tests.append(f"Test 4: DR(16-bit) = {DR:.1f} dB ∈ [96, 100]: {'PASS' if t4 else 'FAIL'}")
        all_passed &= t4
        
        summary = f"QScopeDataModel: {sum(1 for t in tests if 'PASS' in t)}/4 tests passed"
        return all_passed, tests, summary


