# SOLAR WIND MODULATION MODEL
# ═══════════════════════════════════════════════════════════════════════════════

class SolarWindModel:
    """
    Solar Wind Modulation Model for UQFF Framework
    
    ╔═══════════════════════════════════════════════════════════════════════════════╗
    ║  δ_sw - SOLAR WIND MODULATION FACTOR                                          ║
    ╠═══════════════════════════════════════════════════════════════════════════════╣
    ║                                                                               ║
    ║  Definition: δ_sw = Solar wind modulation factor (unitless)                   ║
    ║                                                                               ║
    ║  Value: δ_sw = 0.01                                                           ║
    ║                                                                               ║
    ║  Solar Wind Velocity: v_sw = 5×10⁵ m/s (500 km/s) typical at 1 AU             ║
    ║                                                                               ║
    ║  Solar Wind Modulation Factor:                                                ║
    ║    1 + δ_sw × v_sw = 1 + 0.01 × 5×10⁵ = 5001                                  ║
    ║                                                                               ║
    ║  Role in Ug2 (Outer Field Bubble):                                            ║
    ║    Ug2 = k_2 × [(ρ_vac,[UA] + ρ_vac,[SCm]) × M_s / r²] × S(r - R_b)           ║
    ║          × (1 + δ_sw × v_sw) × H_SCm × E_react                                ║
    ║                                                                               ║
    ║  Physical Interpretation:                                                     ║
    ║    • Solar wind carries energy, momentum, magnetic fields                     ║
    ║    • Creates heliosphere bubble (~120 AU)                                     ║
    ║    • δ_sw scales solar wind's gravitational enhancement                       ║
    ║    • Small δ_sw × large v_sw → significant amplification (5001×)              ║
    ║                                                                               ║
    ║  ©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved      ║
    ╚═══════════════════════════════════════════════════════════════════════════════╝
    """
    
    def __init__(self):
        """Initialize Solar Wind Model with UQFF parameters."""
        # Primary parameters
        self.delta_sw = CONSTANTS.get('delta_sw', 0.01)  # Modulation factor (unitless)
        self.v_sw = CONSTANTS.get('v_sw', 5e5)  # Solar wind velocity (m/s)
        
        # Solar wind velocity range (typical values)
        self.v_sw_min = 3e5  # 300 km/s (slow solar wind)
        self.v_sw_max = 8e5  # 800 km/s (fast solar wind from coronal holes)
        
        # Heliosphere parameters
        self.R_b = CONSTANTS.get('R_b_Sun', 1.496e13)  # 100 AU boundary
        self.heliopause = 122 * 1.496e11  # ~122 AU in meters
        
    def __repr__(self) -> str:
        """String representation with full documentation."""
        sw_factor = self.compute_sw_factor()
        return f"""SolarWindModel
{'═' * 79}
Definition: δ_sw = Solar wind modulation factor

Parameters:
  δ_sw = {self.delta_sw} (unitless)
  v_sw = {self.v_sw:.0e} m/s ({self.v_sw/1e3:.0f} km/s)

Solar Wind Modulation Factor:
  1 + δ_sw × v_sw = 1 + {self.delta_sw} × {self.v_sw:.0e}
                  = {sw_factor:.0f}

Physical Context:
  • Solar wind: stream of charged particles from Sun
  • Velocity range: {self.v_sw_min/1e3:.0f}-{self.v_sw_max/1e3:.0f} km/s
  • Creates heliosphere extending to ~{self.heliopause/1.496e11:.0f} AU
  • Heliopause: boundary where solar wind meets interstellar medium

Role in Ug2:
  Ug2 ∝ (1 + δ_sw × v_sw) = {sw_factor:.0f}× enhancement

Enhancement Comparison:
  Without solar wind (δ_sw=0): factor = 1
  With solar wind (δ_sw=0.01): factor = {sw_factor:.0f}
  Enhancement ratio: {sw_factor:.0f}×

©2025 Daniel T. Murphy, daniel.murphy00@gmail.com – All Rights Reserved
{'═' * 79}
"""
    
    def compute_sw_factor(self, v_sw: float = None, delta_sw: float = None) -> float:
        """
        Compute solar wind modulation factor.
        
        Factor = 1 + δ_sw × v_sw
        
        Args:
            v_sw: Solar wind velocity (m/s), default from instance
            delta_sw: Modulation factor, default from instance
            
        Returns:
            Solar wind factor (unitless)
        """
        if v_sw is None:
            v_sw = self.v_sw
        if delta_sw is None:
            delta_sw = self.delta_sw
            
        return 1 + delta_sw * v_sw
    
    def compute_sw_enhancement(self, v_sw: float = None) -> dict:
        """
        Compute solar wind enhancement details.
        
        Args:
            v_sw: Solar wind velocity (m/s)
            
        Returns:
            Dictionary with enhancement breakdown
        """
        if v_sw is None:
            v_sw = self.v_sw
            
        factor = self.compute_sw_factor(v_sw)
        
        return {
            'delta_sw': self.delta_sw,
            'v_sw': v_sw,
            'v_sw_km_s': v_sw / 1e3,
            'sw_factor': factor,
            'enhancement_ratio': factor,
            'formula': f'1 + {self.delta_sw} × {v_sw:.0e} = {factor:.0f}',
            'interpretation': f'{factor:.0f}× enhancement to Ug2'
        }
    
    def compute_sw_range(self) -> dict:
        """
        Compute solar wind factors across velocity range.
        
        Returns:
            Dictionary with slow/typical/fast solar wind factors
        """
        return {
            'slow_wind': {
                'v_sw': self.v_sw_min,
                'v_sw_km_s': self.v_sw_min / 1e3,
                'factor': self.compute_sw_factor(self.v_sw_min)
            },
            'typical_wind': {
                'v_sw': self.v_sw,
                'v_sw_km_s': self.v_sw / 1e3,
                'factor': self.compute_sw_factor(self.v_sw)
            },
            'fast_wind': {
                'v_sw': self.v_sw_max,
                'v_sw_km_s': self.v_sw_max / 1e3,
                'factor': self.compute_sw_factor(self.v_sw_max)
            },
            'notes': [
                'Slow wind: ~300 km/s (streamer regions)',
                'Typical wind: ~500 km/s (average at 1 AU)',
                'Fast wind: ~800 km/s (coronal holes)'
            ]
        }
    
    def compute_Ug2_with_sw(self, params: dict) -> dict:
        """
        Compute Ug2 with explicit solar wind modulation breakdown.
        
        Args:
            params: Dictionary with M_s, r, R_b, rho_UA, rho_SCm, H_SCm, E_react
            
        Returns:
            Dictionary with Ug2 value and solar wind contribution
        """
        import numpy as np
        
        # Extract parameters
        k_2 = CONSTANTS.get('k_2', 1.2)
        M_s = params.get('M_s', CONSTANTS['M_sun'])
        r = params.get('r', self.R_b)
        R_b = params.get('R_b', self.R_b)
        v_sw = params.get('v_sw', self.v_sw)
        rho_UA = params.get('rho_UA', CONSTANTS.get('rho_vac_UA', 6e-27))
        rho_SCm = params.get('rho_SCm', CONSTANTS.get('rho_vac_SCm', 9.9e-27))
        H_SCm = params.get('H_SCm', CONSTANTS.get('H_SCm', 0.99))
        E_react = params.get('E_react', CONSTANTS.get('E_react', 1e46))
        
        # Combined vacuum density
        rho_total = rho_UA + rho_SCm
        
        # Gravitational term
        grav_term = rho_total * M_s / (r ** 2)
        
        # Step function
        step_function = 1.0 if r >= R_b else 1.0 / (1.0 + np.exp(-10 * (r / R_b - 1)))
        
        # Solar wind modulation
        sw_factor = self.compute_sw_factor(v_sw)
        
        # Ug2 calculation
        Ug2_without_sw = k_2 * grav_term * step_function * H_SCm * E_react
        Ug2_with_sw = Ug2_without_sw * sw_factor
        
        return {
            'Ug2': Ug2_with_sw,
            'Ug2_without_sw': Ug2_without_sw,
            'sw_factor': sw_factor,
            'sw_enhancement': sw_factor,
            'k_2': k_2,
            'rho_total': rho_total,
            'grav_term': grav_term,
            'step_function': step_function,
            'H_SCm': H_SCm,
            'E_react': E_react,
            'unit': 'J/m³',
            'notes': f'Solar wind factor {sw_factor:.0f}× enhances Ug2'
        }
    
    def validate_document_example(self) -> dict:
        """
        Validate against document specification.
        
        Document specifies:
          δ_sw = 0.01
          v_sw = 5×10⁵ m/s
          1 + δ_sw × v_sw = 5001
        
        Returns:
            Dictionary with validation results
        """
        expected_delta_sw = 0.01
        expected_v_sw = 5e5
        expected_factor = 5001
        
        actual_factor = self.compute_sw_factor(expected_v_sw, expected_delta_sw)
        
        return {
            'delta_sw': {
                'expected': expected_delta_sw,
                'computed': self.delta_sw,
                'match': abs(self.delta_sw - expected_delta_sw) < 1e-10
            },
            'v_sw': {
                'expected': expected_v_sw,
                'expected_km_s': expected_v_sw / 1e3,
                'computed': self.v_sw,
                'computed_km_s': self.v_sw / 1e3,
                'match': abs(self.v_sw - expected_v_sw) < 1
            },
            'sw_factor': {
                'expected': expected_factor,
                'computed': actual_factor,
                'match': abs(actual_factor - expected_factor) < 1
            },
            'formula': f'1 + {expected_delta_sw} × {expected_v_sw:.0e} = {actual_factor:.0f}',
            'all_validations_pass': (
                abs(self.delta_sw - expected_delta_sw) < 1e-10 and
                abs(self.v_sw - expected_v_sw) < 1 and
                abs(actual_factor - expected_factor) < 1
            )
        }


